"""Offline interactive view of exactly the reviewed Neo4j import dataset."""
import json
from pathlib import Path
R=Path(__file__).resolve().parent;O=R/'artifacts/semantic10/reviewed'
g=json.loads((O/'graph.json').read_text())
html=r'''<!doctype html><html lang="th"><meta charset="utf-8"><title>คู่มือประชาชน • Knowledge Graph</title>
<style>*{box-sizing:border-box}body{margin:0;background:#0b1221;color:#e5edf9;font:15px system-ui,sans-serif}header{padding:22px 28px;border-bottom:1px solid #283550}h1{font-size:24px;margin:0 0 7px}p{margin:6px 0;color:#afbed4}button,select{padding:9px 12px;background:#1d304b;color:white;border:1px solid #46607e;border-radius:8px;margin:6px 4px 0 0;cursor:pointer}main{display:grid;grid-template-columns:1fr 340px;height:78vh}svg{width:100%;height:100%;touch-action:none}aside{padding:22px;overflow:auto;border-left:1px solid #283550;white-space:pre-wrap;line-height:1.65}circle{stroke:#0b1221;stroke-width:2;cursor:pointer}text{font-size:11px;fill:#e5edf9;pointer-events:none;paint-order:stroke;stroke:#0b1221;stroke-width:3px;stroke-linejoin:round}line{stroke:#6481a2;stroke-opacity:.55;cursor:pointer;stroke-width:2}line:hover{stroke:#fff;stroke-width:5}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:12px;margin-top:10px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}footer{padding:8px 28px;color:#91a5be;font-size:12px}@media(max-width:800px){main{grid-template-columns:1fr;height:auto}svg{height:65vh}aside{height:30vh}}</style>
<header><h1>คู่มือประชาชน → Knowledge Graph</h1><p>PDF หน้า 21–30 • 16 หัวข้อ • 78 entities • 81 relationships • ข้อมูลผ่านการตรวจต้นฉบับโดยผู้ช่วย</p>
<button id="focus">คนหาย · รถหาย · พรากผู้เยาว์</button><button id="all">ภาพรวม</button><button id="shared">หลักฐานที่ใช้ร่วมกัน</button><select id="case"><option value="">เลือกหัวข้อ</option></select><button id="export">บันทึก SVG</button><div class="legend" id="legend"></div></header>
<main><svg id="graph" viewBox="0 0 1100 800" aria-label="Interactive knowledge graph"><defs><marker id="arrow" viewBox="0 -5 10 10" refX="9" refY="0" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,-5L10,0L0,5" fill="#6481a2"/></marker></defs><g id="scene"></g></svg><aside id="detail">เลือกโหนดหรือเส้นเพื่อดูหลักฐาน เลขหน้า และเงื่อนไข<br><br>ลากโหนดเพื่อจัดภาพได้ และใช้ล้อเมาส์เพื่อซูม</aside></main><footer>ภาพนี้แสดงข้อมูลชุดเดียวกับ Neo4j label Task1Reviewed ไม่ใช่ screenshot จาก Neo4j Browser • อ้างอิงคู่มือฉบับที่ให้มา ไม่ได้ตรวจว่าข้อกำหนดยังใช้ในปัจจุบัน</footer>
<script>const data=__DATA__;
const colors={Case:'#60a5fa',Document:'#34d399',Evidence:'#2dd4bf',Contact:'#c084fc',Organization:'#fb923c',PersonRole:'#facc15'},names={Case:'หัวข้อ',Document:'ประเภทเอกสาร',Evidence:'ประเภทหลักฐาน',Contact:'ช่องทางติดต่อ',Organization:'หน่วยงาน',PersonRole:'บทบาทบุคคล'};
const scene=document.querySelector('#scene'),svg=document.querySelector('svg'),panel=document.querySelector('#detail'),byId=new Map(data.nodes.map(n=>[n.id,n]));let state=[],links=[],raf,scale=1;
for(const [k,c] of Object.entries(colors)){const span=document.createElement('span');span.innerHTML='<i class="dot" style="background:'+c+'"></i>'+names[k];document.querySelector('#legend').append(span)}
for(const n of data.nodes.filter(n=>n.type==='Case')){let o=document.createElement('option');o.value=n.section;o.textContent=n.display;document.querySelector('#case').append(o)}
function el(tag,attrs){let e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(let k in attrs)e.setAttribute(k,attrs[k]);return e}
function draw(sections,shared=false){cancelAnimationFrame(raf);scene.replaceChildren();scale=1;scene.removeAttribute('transform');let es=data.edges.filter(e=>!sections||sections.includes(e.section));if(shared){const cnt={};es.forEach(e=>cnt[e.target]=(cnt[e.target]||0)+1);es=es.filter(e=>cnt[e.target]>1&&e.relation==='HAS_SUPPORTING_EVIDENCE')}
const ids=new Set(es.flatMap(e=>[e.source,e.target]));state=data.nodes.filter(n=>ids.has(n.id)).map((n,i)=>({...n,x:550+270*Math.cos(i*2.39996),y:400+260*Math.sin(i*2.39996),vx:0,vy:0}));let map=new Map(state.map(n=>[n.id,n]));links=es.map(e=>({...e,a:map.get(e.source),b:map.get(e.target)}));
links.forEach(e=>{e.el=el('line',{'marker-end':'url(#arrow)'});let t=el('title',{});t.textContent=e.relation;e.el.append(t);e.el.onclick=()=>panel.textContent=e.a.display+'\n↓ '+e.relation+'\n'+e.b.name+'\n\nเงื่อนไข: '+(e.condition||'ไม่ได้ระบุเพิ่ม')+'\nเจ้าของ/บุคคล: '+(e.owner||'ไม่ได้ระบุ')+'\nPDF หน้า '+e.pdf_pages.join(', ')+' / เลขพิมพ์ '+e.printed_pages.join(', ')+'\n\nข้อความอ้างอิง:\n'+e.evidence+'\n\nสถานะ: '+e.review_status;scene.append(e.el)});
state.forEach(n=>{let group=el('g',{});n.el=group;let c=el('circle',{r:n.type==='Case'?24:15,fill:colors[n.type]});let t=el('text',{'text-anchor':'middle',y:n.type==='Case'?40:29});t.textContent=n.type==='Case'?n.section+' '+n.name:n.name;group.append(c,t);scene.append(group);c.onclick=()=>panel.textContent=n.display+'\n'+names[n.type]+'\nPDF หน้า '+n.pdf_pages.join(', ')+'\n\n'+(n.kind==='concept_type'?'โหนดนี้แทนประเภทเอกสาร/หลักฐาน เจ้าของจริงเก็บไว้บนแต่ละเส้น\n\n':'')+links.filter(e=>e.source===n.id||e.target===n.id).map(e=>e.a.display+' → '+e.relation+' → '+e.b.name).join('\n\n');c.onpointerdown=ev=>{ev.preventDefault();c.setPointerCapture(ev.pointerId);n.drag=true;c.onpointermove=e=>{let p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;p=p.matrixTransform(scene.getScreenCTM().inverse());n.x=p.x;n.y=p.y;update()};c.onpointerup=()=>{n.drag=false;c.onpointermove=null}}});let tick=0;
function step(){for(let n of state){n.vx+=(550-n.x)*.0006;n.vy+=(400-n.y)*.0006}for(let i=0;i<state.length;i++)for(let j=i+1;j<state.length;j++){let a=state[i],b=state[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.max(80,dx*dx+dy*dy),f=500/d;a.vx+=dx*f/Math.sqrt(d);a.vy+=dy*f/Math.sqrt(d);b.vx-=dx*f/Math.sqrt(d);b.vy-=dy*f/Math.sqrt(d)}for(let e of links){let dx=e.b.x-e.a.x,dy=e.b.y-e.a.y,d=Math.hypot(dx,dy)||1,f=(d-145)*.006;e.a.vx+=dx/d*f;e.a.vy+=dy/d*f;e.b.vx-=dx/d*f;e.b.vy-=dy/d*f}for(let n of state){n.vx*=.75;n.vy*=.75;if(!n.drag){n.x=Math.max(115,Math.min(985,n.x+n.vx));n.y=Math.max(45,Math.min(745,n.y+n.vy))}}update();if(++tick<450){if(tick<400)step();else raf=requestAnimationFrame(step)}}step()}
function update(){state.forEach(n=>n.el.setAttribute('transform',`translate(${n.x},${n.y})`));links.forEach(e=>{let dx=e.b.x-e.a.x,dy=e.b.y-e.a.y,d=Math.hypot(dx,dy)||1;for(let [k,v]of Object.entries({x1:e.a.x+dx/d*25,y1:e.a.y+dy/d*25,x2:e.b.x-dx/d*18,y2:e.b.y-dy/d*18}))e.el.setAttribute(k,v)})}
svg.onwheel=e=>{e.preventDefault();scale=Math.max(.45,Math.min(3,scale*(e.deltaY>0?.9:1.1)));scene.setAttribute('transform',`translate(${550*(1-scale)},${400*(1-scale)}) scale(${scale})`)};
document.querySelector('#focus').onclick=()=>draw(['1.4','1.5','1.13']);document.querySelector('#all').onclick=()=>draw(null);document.querySelector('#shared').onclick=()=>draw(null,true);document.querySelector('#case').onchange=e=>{if(e.target.value)draw([e.target.value])};document.querySelector('#export').onclick=()=>{let copy=svg.cloneNode(true);let style=el('style',{});style.textContent=document.querySelector('style').textContent;copy.prepend(style);copy.setAttribute('xmlns','http://www.w3.org/2000/svg');copy.style.background='#0b1221';const u=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'}));let a=document.createElement('a');a.href=u;a.download='knowledge-graph.svg';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};draw(['1.4','1.5','1.13']);</script></html>'''
(O/'graph.html').write_text(html.replace('__DATA__',json.dumps(g,ensure_ascii=False).replace('<','\\u003c')))
print(O/'graph.html')
